(()=>{
const BANK=(window.ODD_BANK&&window.ODD_BANK.questions)||[];
const A=window.ODD_ASSETS||{};
const app=document.getElementById('app');
const state={player:localStorage.getItem('oddPlayer')||'Rick',mode:'home',seed:'',rng:Math.random,round:[],idx:0,score:0,correct:0,streak:0,best:0,miniWins:0,bossWins:0,seen:new Set(JSON.parse(localStorage.getItem('oddSeenV4')||'[]')),challenge:null,category:null,lock:false};
const qs=s=>document.querySelector(s); const qsa=s=>[...document.querySelectorAll(s)];
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){let a=hash(seed);return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function pick(arr,r=state.rng){return arr[Math.floor(r()*arr.length)]}
function shuffle(arr,r=state.rng){arr=[...arr];for(let i=arr.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]]}return arr}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function vibrate(x){try{navigator.vibrate&&navigator.vibrate(x)}catch(e){}}
function img(src,cls=''){return `<img class="${cls}" src="${src}" alt=""/>`}
function todaySeed(){let d=new Date();return `daily-${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function screen(html,cls=''){app.innerHTML=`<main class="screen ${cls}">${html}</main>`;window.scrollTo(0,0)}
function persistSeen(){localStorage.setItem('oddSeenV4',JSON.stringify([...state.seen].slice(-600)))}
function setPlayer(p){state.player=p;localStorage.setItem('oddPlayer',p);renderHome()}
function challengeInfo(){const u=new URL(location.href);if(u.searchParams.get('seed')) return {seed:u.searchParams.get('seed'),from:u.searchParams.get('from')||'?',score:Number(u.searchParams.get('score')||0)};return null}
state.challenge=challengeInfo();

const CATS=[
 ['OUR STORY','💞','Actual lore, stupid moments, relationship archaeology'],
 ['MUSIC NERD-OFF','🎧','Hip-hop, metal, rabbit holes, gigs and records'],
 ['FOOD & DRINK','🍺','Greggs doctrine, Tap science and beverage crimes'],
 ['FESTIVAL CHAOS','⛺','Kendal, broken tents, toilets and poor decisions'],
 ['TAP & LOCAL','🍻','Tap o’clock, Denise, Will and local mythology'],
 ['ANIMALS','🐈','Animals, weird biology and creatures doing nonsense'],
 ['HISTORY','🏰','Real history that sounds made up'],
 ['PSYCHOLOGY','🧠','Brains behaving badly'],
 ['HUMAN BODY','💀','Gross, clever and inexplicable human machinery']
];
function renderHome(){state.mode='home';const ch=state.challenge;
screen(`<section class="home">
 <div class="hero">${A.couple?img(A.couple,'heroArt'):''}<div class="heroTitle">RICK <span style="color:#fff">&</span> LAURA<b>CHAOS QUIZ</b></div><div class="heroTag">WEIRD QUESTIONS • STUPID GAMES</div><div class="heroDoodle one">greggs // gigs // pub nonsense</div><div class="heroDoodle two">our world →</div></div>
 <div class="homeLead">Not a relationship test. More like your WhatsApp archive got drunk and became a gameshow.</div>
 ${ch?`<div class="challengeBanner"><b>${esc(ch.from)} has sent you a chaos run.</b><br/>Same round. Their score stays hidden until you finish.</div>`:''}
 <div class="whoPick"><button class="${state.player==='Rick'?'on':''}" id="pRick">I'M RICK</button><button class="${state.player==='Laura'?'on':''}" id="pLaura">I'M LAURA</button></div>
 <div class="mainActions">
 ${ch?`<button class="bigbtn chaos" id="accept"><span class="ico">💣</span><div><strong>ACCEPT CHALLENGE</strong><span>Same chaos. No excuses.</span></div></button>`:`<button class="bigbtn chaos" id="chaos"><span class="ico">🎮</span><div><strong>CHAOS RUN</strong><span>Questions, microgames, interruptions + boss fight.</span></div></button>`}
 <button class="bigbtn challenge" id="challenge"><span class="ico">🥊</span><div><strong>CHALLENGE MODE</strong><span>You play. Send the exact same run to ${state.player==='Rick'?'Laura':'Rick'}.</span></div></button>
 <button class="bigbtn daily" id="daily"><span class="ico">📅</span><div><strong>DAILY ROUND</strong><span>One shared episode every day.</span></div></button>
 <button class="bigbtn choose" id="cats"><span class="ico">🧩</span><div><strong>CHOOSE A CATEGORY</strong><span>Pick your particular flavour of bullshit.</span></div></button>
 </div>
 <div class="homeNav"><div class="navitem">🏆<span class="navlab">SCORES</span></div><div class="navitem">🎖️<span class="navlab">BADGES</span></div><div class="navitem">📚<span class="navlab">LORE</span></div><div class="navitem">⚙️<span class="navlab">SETTINGS</span></div></div>
 <div class="ticker"><span>WEALTHY LITTLE PIGS</span><i>✦</i><span>43 MINNIE'S</span><i>✦</i><span>ALL IS WORKABLE</span><i>✦</i><span>TAPPPPPPPPPP</span></div>
 </section>`,'home');
 qs('#pRick').onclick=()=>setPlayer('Rick');qs('#pLaura').onclick=()=>setPlayer('Laura');
 if(qs('#accept'))qs('#accept').onclick=()=>startRun('challenge',ch.seed);
 qs('#chaos')&& (qs('#chaos').onclick=()=>startRun('chaos'));
 qs('#challenge').onclick=()=>startRun('share');qs('#daily').onclick=()=>startRun('daily',todaySeed());qs('#cats').onclick=renderCategories;
}
function renderCategories(){screen(`<div class="top"><button class="back" id="back">←</button><div class="score">CHOOSE YOUR POISON</div></div><div class="categoryHead"><h1>WHAT KIND OF CHAOS?</h1><p>Each category has its own question pool. Chaos Run mixes all of them with games.</p></div><div class="categoryGrid">${CATS.map(([c,e,d])=>`<button class="catCard" data-cat="${esc(c)}"><div class="emoji">${e}</div><h3>${esc(c)}</h3><p>${esc(d)}</p></button>`).join('')}</div>`);
 qs('#back').onclick=renderHome;qsa('.catCard').forEach(b=>b.onclick=()=>startRun('category',null,b.dataset.cat));}
function eligibleQuestions(category=null){if(!category)return BANK;const related={
 'OUR STORY':['OUR STORY','OUR CHAT'],
 'MUSIC NERD-OFF':['MUSIC NERD-OFF'],
 'FOOD & DRINK':['FOOD & DRINK','FOOD, DRINK & PUB'],
 'FESTIVAL CHAOS':['FESTIVAL CHAOS','TRAVEL & CHAOS'],
 'TAP & LOCAL':['TAP & LOCAL','TAP & PEOPLE','DAD LORE','FOOD, DRINK & PUB'],
 'ANIMALS':['ANIMALS','ANIMALS & PETS'],
 'HISTORY':['HISTORY','WEIRD SHIT'],
 'PSYCHOLOGY':['PSYCHOLOGY','WEIRD SHIT'],
 'HUMAN BODY':['HUMAN BODY','BODY WEIRDNESS','WEIRD SHIT']};
 let cats=related[category]||[category];let arr=BANK.filter(q=>cats.includes(q.category));if(arr.length<8)arr=arr.concat(BANK.filter(q=>q.pool==='main'&&!arr.includes(q)));return arr}
function buildRun(seed,category=null,chaos=true){state.rng=rng(seed);let all=eligibleQuestions(category);let main=all.filter(q=>q.pool==='main');let archive=all.filter(q=>q.pool==='archive');const unseen=q=>!state.seen.has(q.id);let chosen=[];
 function take(pool,n){let u=shuffle(pool.filter(unseen));let s=u.slice(0,n);if(s.length<n)s=s.concat(shuffle(pool.filter(q=>!s.includes(q))).slice(0,n-s.length));chosen.push(...s)}
 if(category){take(main,6);take(archive,4)}else{take(main,6);take(archive,2)}
 chosen=shuffle(chosen).slice(0,chaos?8:10);
 if(chaos){let minis=shuffle(['savvy','clock','glasses','greggs','m6','tent']);let out=[];chosen.forEach((q,i)=>{out.push({kind:'q',q});if(i===1)out.push({kind:'mini',game:minis[0]});if(i===4)out.push({kind:'mini',game:minis[1]});});out.push({kind:'boss'});return out}
 return chosen.map(q=>({kind:'q',q}));}
function startRun(mode,seed=null,category=null){state.mode=mode;state.seed=seed||`${mode}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;state.category=category;state.round=buildRun(state.seed,category,mode!=='category');state.idx=0;state.score=0;state.correct=0;state.streak=0;state.best=0;state.miniWins=0;state.bossWins=0;state.lock=false;showRound();}
function topbar(kind='q'){let dots=state.round.map((r,i)=>`<i class="${i<state.idx?'on':''} ${r.kind==='mini'?'mini':''} ${r.kind==='boss'?'boss':''}"></i>`).join('');return `<div class="top"><button class="back" id="quit">←</button><div class="roundp">${dots}</div><div class="score">${state.score.toLocaleString()}</div></div>`}
function showRound(){if(state.idx>=state.round.length)return showResults();let item=state.round[state.idx];if(item.kind==='q')showQuestion(item.q);else if(item.kind==='mini')miniIntro(item.game);else bossIntro();}
function showQuestion(q){state.lock=false;let who=q.type==='who';let timeline=q.type==='timeline';let chat=q.type==='finish'||q.type==='next'||q.type==='who';let prompt=q.prompt.replace(/^WHO SAID IT\?\n/i,'').replace(/^FINISH THE ACTUAL MESSAGE\n/i,'').replace(/^WHAT DID .*? ACTUALLY SEND NEXT\?\n/i,'').replace(/^WHICH HAPPENED FIRST\?\n/i,'').replace(/^WHEN DID THIS LAND\?\n/i,'');
 let content=`${topbar()}<div class="gameBody"><div class="qmeta">${esc(q.category)} · ROUND ${state.idx+1}</div>${chat?`<div class="chatBubble">${esc(prompt)}<small>${q.date?esc(q.date):'from the archive'}</small></div>`:`<div class="paper"><h2>${esc(prompt)}</h2>${q.date?`<div class="date">CHAT ARCHIVE • ${esc(q.date)}</div>`:''}</div>`}`;
 if(who){content+=`<div class="whoSaid"><button class="personBtn rick" data-i="0">${A.rick?img(A.rick):''}<b>RICK</b></button><button class="personBtn laura" data-i="1">${A.laura?img(A.laura):''}<b>LAURA</b></button></div>`}
 else if(timeline){content+=`<div class="timelineGrid">${q.options.map((o,i)=>`<button class="event" data-i="${i}"><small>${i===0?'EVENT A':'EVENT B'}</small><strong>${esc(o)}</strong></button>`).join('')}</div>`}
 else{content+=`<div class="answerList">${q.options.map((o,i)=>`<button class="ans" data-i="${i}"><span class="key">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>`}
 content+=`<div id="reveal"></div></div>`;screen(content,'game');qs('#quit').onclick=()=>confirmQuit();qsa('[data-i]').forEach(b=>b.onclick=()=>answerQuestion(q,Number(b.dataset.i),b));}
function answerQuestion(q,i,btn){if(state.lock)return;state.lock=true;let ok=i===q.answer;state.seen.add(q.id);persistSeen();if(ok){state.correct++;state.streak++;state.best=Math.max(state.best,state.streak);state.score+=100+state.streak*20;vibrate(35)}else{state.streak=0;vibrate([70,40,70])}
 qsa('[data-i]').forEach((b,j)=>{if(j===q.answer)b.classList.add('good');else if(j===i)b.classList.add('bad');b.disabled=true});let title=ok?pick(['ABSOLUTE SCENES','CORRECT, YOU NERD','BEHBEH KNOWS','UNREASONABLY LOCKED IN']):pick(['OH BEHBEH…','NOPE 😂','THE ARCHIVE DISAGREES','CATASTROPHIC']);qs('#reveal').innerHTML=`<div class="reveal ${ok?'good':'bad'}"><h3>${title}</h3><p>${esc(q.reveal)}</p></div><button class="next" id="next">NEXT →</button>`;qs('#next').onclick=nextRound;}
function nextRound(){state.idx++;showRound()}
function confirmQuit(){if(confirm('Abort this run and go back to the pub?'))renderHome()}

function miniIntro(game){let map={savvy:['SAVE THE SAVVY B!','Stop the pour inside the sweet spot.',A.laura],clock:["TAP O'CLOCK",'Stop the clock as close to 4:00 as you can.',A.rick],glasses:["FIND RICK'S GLASSES",'They are absolutely somewhere obvious.',A.rick],greggs:['GREGGS DOCTRINE','Tap the sausage rolls. Ignore all heresy.',A.laura],m6:['ESCAPE THE M6','Change lanes. Do not become traffic.',A.rick],tent:['FIX THE FESTIVAL','Broken tent pole. One tool saves Kendal.',A.laura]};let [t,s,art]=map[game];screen(`<div class="interstitial"><div class="blast"><div class="microKicker">MICROGAME INCOMING</div><h1>${t}</h1>${art?img(art):''}<p>${s}</p></div></div>`);setTimeout(()=>runMini(game),1150)}
function miniShell(title,sub,stage,buttons=''){screen(`${topbar('mini')}<section class="microScreen"><div class="microHead"><div class="microKicker">⚡ MICROGAME</div><h1>${title}</h1><p>${sub}</p></div><div class="microStage" id="microStage">${stage}</div><div class="microBottom">${buttons}</div></section>`);qs('#quit').onclick=()=>confirmQuit()}
function miniWin(text,pts=180){state.miniWins++;state.score+=pts;vibrate([30,20,30]);microResult(true,text)}function miniLose(text){vibrate([90,40,90]);microResult(false,text)}
function microResult(ok,text){screen(`<div class="interstitial"><div class="blast"><div class="microKicker">${ok?'MICROGAME CLEARED':'MICROGAME FAILED'}</div><h1 style="color:${ok?'var(--lime)':'var(--red)'}">${ok?'NAILED IT':'DISASTER'}</h1>${ok&&A.couple?img(A.couple):A.rick?img(A.rick):''}<p>${esc(text)}</p><button class="next" id="continue">KEEP GOING →</button></div></div>`);qs('#continue').onclick=nextRound}
function runMini(g){({savvy:miniSavvy,clock:miniClock,glasses:miniGlasses,greggs:miniGreggs,m6:miniM6,tent:miniTent}[g]||miniGlasses)()}
function miniSavvy(){let target=55+Math.floor(state.rng()*20),pos=0,dir=1,done=false;miniShell('SAVE THE SAVVY B!','Stop the marker inside the green pour zone.',`<div class="wineglass">🍷</div>${A.laura?img(A.laura,'microCharacter'):''}<div class="meterTrack"><div class="target" style="left:${target}%;width:17%"></div><div class="marker" id="marker"></div></div><div class="microTimer">6s</div>`,`<button class="microBtn" id="stop">STOP THE POUR!</button>`);let start=performance.now();function frame(t){if(done)return;let elapsed=(t-start)/1000;pos+=dir*1.25;if(pos>=98||pos<=0)dir*=-1;qs('#marker').style.left=pos+'%';qs('.microTimer').textContent=Math.max(0,6-Math.floor(elapsed))+'s';if(elapsed>=6){done=true;miniLose('Savvy B everywhere. Laura has filed a complaint.');return}requestAnimationFrame(frame)}requestAnimationFrame(frame);qs('#stop').onclick=()=>{if(done)return;done=true;pos>=target&&pos<=target+17?miniWin('Steady… steady… PERFECT pour.'):miniLose('Too much confidence. The table is now wine.')};}
function miniClock(){let angle=0,done=false;miniShell("TAP O'CLOCK",'Stop the hand on four. Dad-level pub punctuality required.',`<div class="clockFace"><div class="hand" id="hand"></div></div><div class="microTimer">5s</div>`,`<button class="microBtn" id="stop">STOP THE CLOCK</button>`);let start=performance.now();function f(t){if(done)return;angle=(t-start)*.22%360;qs('#hand').style.transform=`rotate(${angle}deg)`;qs('.microTimer').textContent=Math.max(0,5-Math.floor((t-start)/1000))+'s';if(t-start>5000){done=true;miniLose('You missed Tap o’clock. Swan Blonde has gone emotionally cold.');return}requestAnimationFrame(f)}requestAnimationFrame(f);qs('#stop').onclick=()=>{if(done)return;done=true;let target=120;let diff=Math.min(Math.abs(angle-target),360-Math.abs(angle-target));diff<22?miniWin('4pm. Tap o’clock. The universe is aligned.'):miniLose('That is not four o’clock. Pub ritual violated.')};}
function miniGlasses(){let icons=['🕶️','🔑','📱','☕','🎧','🧢','🍺','🎟️','🪙','🎤','🧦','🧻','🥤','🔌','🧴'];let spot=Math.floor(state.rng()*16);let cells=Array.from({length:16},(_,i)=>`<button class="clutter" data-x="${i}">${i===spot?'👓':pick(icons)}</button>`).join('');miniShell("FIND RICK'S GLASSES",'You have six seconds. They are obviously right there.',`<div class="microTimer">6s</div><div class="glassesGrid">${cells}</div>`,``);let done=false,t=setTimeout(()=>{if(!done){done=true;miniLose('Object permanence loses again.')}},6000);qsa('.clutter').forEach(b=>b.onclick=()=>{if(done)return;if(Number(b.dataset.x)===spot){done=true;clearTimeout(t);miniWin('Found them. Now locate the car.')}else{b.style.opacity=.25;vibrate(25)}})}
function miniGreggs(){let items=['🥐','🥖','🥧','🍩','🥪','🍕','🥯','🧁'];let sausage=[1,4,7,10];let cells=Array.from({length:12},(_,i)=>`<button class="foodTile" data-s="${sausage.includes(i)?1:0}">${sausage.includes(i)?'🌭':pick(items)}</button>`).join('');miniShell('GREGGS DOCTRINE','Tap all four sacred sausage rolls. Wrong pastry = heresy.',`<div class="microTimer">6s</div><div class="greggsGrid">${cells}</div>`,``);let left=4,done=false,t=setTimeout(()=>{if(!done){done=true;miniLose('The summons was ignored. Greggs remembers.')}},6000);qsa('.foodTile').forEach(b=>b.onclick=()=>{if(done||b.disabled)return;if(b.dataset.s==='1'){b.disabled=true;b.style.background='#264326';b.textContent='✅';left--;if(left===0){done=true;clearTimeout(t);miniWin('Nothing more, nothing less. Scripture upheld.')}}else{done=true;clearTimeout(t);miniLose('You selected an illegal pastry. Laura is disappointed.')}})}
function miniM6(){miniShell('ESCAPE THE M6','Tap left/right to dodge traffic for seven seconds.',`<div class="road" id="road"><div class="playerCar" id="car">🚙</div></div><div class="microTimer">7s</div>`,`<div class="roadControls"><button id="left">←</button><button id="right">→</button></div>`);let lane=1,done=false,obs=[],start=performance.now();const laneX=[15,48,79];function place(){qs('#car').style.left=`calc(${laneX[lane]}% - 26px)`}place();qs('#left').onclick=()=>{lane=Math.max(0,lane-1);place()};qs('#right').onclick=()=>{lane=Math.min(2,lane+1);place()};let spawn=setInterval(()=>{if(done)return;let l=Math.floor(state.rng()*3),el=document.createElement('div');el.className='obstacle';el.style.left=`calc(${laneX[l]}% - 24px)`;el.style.top='-80px';el.textContent=pick(['🚗','🚕','🚐','🚚']);qs('#road').appendChild(el);obs.push({el,l,y:-80})},650);function loop(t){if(done)return;let elapsed=(t-start)/1000;qs('.microTimer').textContent=Math.max(0,7-Math.floor(elapsed))+'s';for(let o of obs){o.y+=4.6;o.el.style.top=o.y+'px';if(o.y>340&&o.y<440&&o.l===lane){done=true;clearInterval(spawn);miniLose('Standstill traffic wins again. Classic M6.');return}}obs=obs.filter(o=>o.y<550);if(elapsed>=7){done=true;clearInterval(spawn);miniWin('You escaped the M6. Historically unprecedented.');return}requestAnimationFrame(loop)}requestAnimationFrame(loop)}
function miniTent(){let tools=[['🩹','GAFFER TAPE'],['🥄','WOODEN SPOON'],['🎀','RIBBON'],['🍺','A PINT'],['🧵','THREAD'],['🙏','HOPE']];miniShell('FIX THE FESTIVAL','Broken pole. Pick the canon repair before Kendal collapses.',`<div class="tentPole"></div><div class="microTimer">5s</div><div class="toolGrid">${tools.map((x,i)=>`<button class="tool" data-t="${i}">${x[0]}<span style="display:block;font-size:9px">${x[1]}</span></button>`).join('')}</div>`,``);let done=false,t=setTimeout(()=>{if(!done){done=true;miniLose('Tent down. Festival verb cancelled.')}},5000);qsa('.tool').forEach(b=>b.onclick=()=>{if(done)return;done=true;clearTimeout(t);Number(b.dataset.t)===0?miniWin('Gaffer tape. All is workable.'):miniLose('Wrong. The answer was always gaffer tape.')})}

function bossIntro(){screen(`<div class="interstitial"><div class="blast"><div class="microKicker">BOSS ENCOUNTER</div><h1 style="color:var(--red)">FATS VS THE ROAST</h1><div style="font-size:120px">🍽️😡🍗</div><p>The pub has no Sunday roast. This is now everybody's problem.</p><button class="next" id="fight">FIGHT THE ROAST CRISIS</button></div></div>`);qs('#fight').onclick=runBoss}
function runBoss(){let hp=100,round=0;const bossQs=BANK.filter(q=>q.category==='FATS LORE'||q.category==='FOOD & DRINK').slice(0,20);function phase(){if(hp<=0){state.bossWins++;state.score+=400;return microResult(true,'Roast secured. Fats may stand down.')}if(round>=4)return microResult(false,'The roast crisis has overwhelmed local government.');let q=pick(bossQs);let opts=shuffle(q.options.map((o,i)=>({o,i})));screen(`${topbar('boss')}<section class="microScreen"><div class="microHead"><div class="microKicker">BOSS FIGHT · PHASE ${round+1}</div><h1>FATS VS THE ROAST</h1><p>Correct answer = damage. Wrong answer = indignation.</p></div><div class="microStage"><div class="bossTitle">NO ROAST?!</div><div class="hpWrap"><div class="hp" style="width:${hp}%"></div></div><div class="roastBoss"><i class="bossEye a"></i><i class="bossEye b"></i><i class="bossMouth"></i></div><div class="bossChoice">${opts.map(x=>`<button data-boss="${x.i}">${esc(x.o)}</button>`).join('')}</div></div></section>`);qs('#quit').onclick=confirmQuit;qsa('[data-boss]').forEach(b=>b.onclick=()=>{let ok=Number(b.dataset.boss)===q.answer;if(ok){hp-=30;state.score+=120;vibrate(35)}else{vibrate([80,40,80])}round++;phase()})}phase()}

function showResults(){let opp=state.challenge&&state.challenge.score?state.challenge.score:null;let totalQ=state.round.filter(x=>x.kind==='q').length;let verdict=state.correct>=Math.ceil(totalQ*.75)?'DISTURBINGLY LOCKED IN':state.correct>=Math.ceil(totalQ*.5)?'RESPECTABLE CHAOS':'ABSOLUTE SHAMBLES';if(opp!==null)verdict=state.score>opp?'YOU COOKED THEM':state.score<opp?'YOU GOT COOKED':'FILTHY DRAW';screen(`<section class="result"><div class="resultHero"><div class="confetti"></div>${A.couple?img(A.couple):''}<div class="resultText">ROUND<br/>COMPLETE!</div></div><div class="resultPanel"><div class="bigScore">${state.score.toLocaleString()}</div><div style="text-align:center;font-family:'Permanent Marker';font-size:18px">${verdict}</div>${opp!==null?`<div style="text-align:center;margin:8px 0;color:#cfc5d3"><b>${esc(state.challenge.from)}</b> ${opp.toLocaleString()} &nbsp; VS &nbsp; <b>${state.player}</b> ${state.score.toLocaleString()}</div>`:''}<div class="stats"><div class="stat"><small>RIGHT ANSWERS</small><b>${state.correct}</b></div><div class="stat"><small>BEST STREAK</small><b>${state.best}</b></div><div class="stat"><small>MICROGAMES</small><b>${state.miniWins}</b></div><div class="stat"><small>BOSS STATUS</small><b>${state.bossWins?'DEFEATED':'FERAL'}</b></div></div>${opp===null?`<button class="shareBtn pink" id="share">CHALLENGE ${state.player==='Rick'?'LAURA':'RICK'} →</button>`:''}<button class="shareBtn" id="again">PLAY ANOTHER ROUND</button><button class="shareBtn secondary" id="home">BACK TO MENU</button></div></section>`,'result');if(qs('#share'))qs('#share').onclick=shareChallenge;qs('#again').onclick=()=>startRun(state.mode==='daily'?'chaos':state.mode);qs('#home').onclick=()=>{history.replaceState({},'',location.pathname);state.challenge=null;renderHome()}}
async function shareChallenge(){let u=new URL(location.href);u.search='';u.searchParams.set('seed',state.seed);u.searchParams.set('from',state.player);u.searchParams.set('score',String(state.score));let txt=`I scored ${state.score.toLocaleString()} on Rick & Laura Chaos Quiz. Your turn 😈`;try{if(navigator.share)await navigator.share({title:'Rick & Laura Chaos Quiz',text:txt,url:u.toString()});else{await navigator.clipboard.writeText(u.toString());alert('Challenge link copied')}}catch(e){}}
renderHome();
})();